<?php
namespace App\Domain\AI\Channels\WhatsApp\Services;
use App\Domain\AI\Actions\Models\ActionRun;use App\Domain\AI\Actions\Services\ConfirmActionRunService;use App\Domain\AI\Channels\WhatsApp\Models\{WhatsAppChannel,WhatsAppDelivery,WhatsAppSession};use App\Domain\AI\Conversations\Models\ConversationMessage;use App\Models\User;use Illuminate\Support\Facades\DB;
final class ConfirmWhatsAppActionService{
 public function __construct(private ConfirmActionRunService$core,private WhatsAppDeliveryService$deliveries){}
 public function handle(WhatsAppChannel$c,WhatsAppSession$s,string$reply):void{if(!preg_match('/^(confirm|cancel)_([A-Za-z0-9_-]{43})$/D',$reply,$m))throw new \DomainException('confirmation_unavailable');$d=WhatsAppDelivery::where('confirmation_token_hash',hash('sha256',$m[2]))->firstOrFail();if($m[1]==='cancel'){$this->cancel($c,$s,$d);return;}$a=ActionRun::whereKey($d->action_run_id)->firstOrFail();$authorize=function(ActionRun$pending)use($c,$s,$d){$channel=WhatsAppChannel::whereKey($c->id)->lockForUpdate()->firstOrFail();$session=WhatsAppSession::where('whatsapp_channel_id',$channel->id)->whereKey($s->id)->lockForUpdate()->firstOrFail();$delivery=WhatsAppDelivery::where('whatsapp_session_id',$session->id)->whereKey($d->id)->lockForUpdate()->firstOrFail();if(!$channel->enabled||!$session->insideWindow()||$delivery->confirmed_at||$delivery->confirmation_expires_at?->isPast()||(int)$session->conversation_id!==(int)$pending->conversation_id||(int)$channel->tenant_id!==(int)$pending->tenant_id||(int)$channel->agent_id!==(int)$pending->agent_id)throw new \DomainException('confirmation_unavailable');$delivery->confirmed_at=now();$delivery->save();};$message=$this->core->confirm(User::findOrFail($c->created_by_user_id),$a,$authorize);$this->deliveries->text($c,$s,$message);}
 private function cancel(WhatsAppChannel$c,WhatsAppSession$s,WhatsAppDelivery$d):void{DB::transaction(function()use($c,$s,$d){$channel=WhatsAppChannel::lockForUpdate()->findOrFail($c->id);$session=WhatsAppSession::where('whatsapp_channel_id',$channel->id)->lockForUpdate()->findOrFail($s->id);$delivery=WhatsAppDelivery::where('whatsapp_session_id',$session->id)->lockForUpdate()->findOrFail($d->id);if(!$channel->enabled||!$session->insideWindow()||$delivery->confirmed_at||$delivery->confirmation_expires_at?->isPast())throw new \DomainException('confirmation_unavailable');$delivery->confirmed_at=now();$delivery->status='cancelled';$delivery->save();});}
}
